from itertools import product

def pieces_for(grid):
    H,W=len(grid),len(grid[0]); cells={(r,c) for r in range(H) for c in range(W) if grid[r][c]==8}
    pieces=[]
    for r in range(H-1):
      for c in range(W-1):
        block={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
        if block<=cells: pieces.append((block,1,'square',r,c))
        for missing,color in [((r,c),2),((r+1,c),3),((r,c+1),4),((r+1,c+1),5)]:
          shape=block-{missing}
          if shape<=cells: pieces.append((shape,color,'L',r,c))
    return cells,pieces

def exact_covers(grid):
    cells,pieces=pieces_for(grid)
    bycell={cell:[p for p in pieces if cell in p[0]] for cell in cells}
    sols=[]
    def rec(rem, chosen):
      if not rem:
        sols.append(chosen[:]); return
      cell=min(rem,key=lambda x:sum(p[0]<=rem for p in bycell[x]))
      for p in bycell[cell]:
        if p[0] <= rem:
          rec(rem-p[0],chosen+[p])
    rec(cells,[])
    return sols
