def candidate_transform(grid):
    h,w=len(grid),len(grid[0]); cells={(r,c) for r in range(h) for c in range(w) if grid[r][c]==8}; pieces=[]
    for r in range(h-1):
        for c in range(w-1):
            sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
            if sq<=cells: pieces.append((sq,1))
            for missing,color in [((r,c),2),((r+1,c),3),((r,c+1),4),((r+1,c+1),5)]:
                s=sq-{missing}
                if s<=cells: pieces.append((s,color))
    bycell={p:[] for p in cells}
    for shape,color in pieces:
        for p in shape: bycell[p].append((shape,color))
    def solve(rem,out):
        if not rem: return out
        cell=min(rem,key=lambda p:sum(shape<=rem for shape,color in bycell[p]))
        for shape,color in bycell[cell]:
            if shape<=rem:
                ans=solve(rem-shape,out+[(shape,color)])
                if ans is not None:return ans
        return None
    tiling=solve(cells,[])
    if tiling is None: raise ValueError('no tiling')
    ans=[[0]*w for _ in range(h)]
    for shape,color in tiling:
        for r,c in shape: ans[r][c]=color
    return ans
